const transliteration = {
    ё: 'yo',
    й: 'i',
    ц: 'ts',
    у: 'u',
    к: 'k',
    е: 'e',
    н: 'n',
    г: 'g',
    ш: 'sh',
    щ: 'sch',
    з: 'z',
    х: 'h',
    ъ: 'hard',
    ф: 'f',
    ы: 'y',
    в: 'v',
    а: 'a',
    п: 'p',
    р: 'r',
    о: 'o',
    л: 'l',
    д: 'd',
    ж: 'zh',
    э: 'ae',
    я: 'ya',
    ч: 'ch',
    с: 's',
    м: 'm',
    и: 'i',
    т: 't',
    ь: 'soft',
    б: 'b',
    ю: 'yu',
};
export const transliterate = (word = '') => {
    return word
        .toLowerCase()
        .split('')
        .map((char) => (char in transliteration ? transliteration[char] : char))
        .join('');
};
